-- A-14 (S01, 2026-10-19): instantánea de privilegios y storage que vivían solo en producción.
-- NO cambia comportamiento: reproduce el estado leído de prod el 2026-10-19. Hasta hoy el baseline no
-- tenía ningún GRANT y faltaban 4 buckets y 4 políticas de storage, así que recrear el entorno desde
-- las migraciones daba otros privilegios.
--
-- 1. Buckets: los 9 vigentes, con su flag `public`, tamaño máximo y tipos MIME (idempotente).
--    Nota: el bucket `org-assets` que usa `uploadOrgLogo` (src/app/actions/config.ts) NO existe en
--    prod; no se crea aquí porque cambiaría el comportamiento (hallazgo nuevo, ver el plan).
-- 2. Políticas de storage que no estaban en ninguna migración (handover-packages, pid-documents).
--    El resto ya está versionado (20261012210000 y siguientes).
-- 3. EXECUTE de cada función de public para PUBLIC/anon/authenticated/service_role, tal cual está.
--    Las 23 ejecutables por anon y las 16 con PUBLIC se corrigen en S02 (A-19), no aquí.
-- 4. Tablas y vistas que se desvían del estándar Supabase (ALL a los tres roles): itr_signatures
--    (inmutable: ni service_role la modifica) y las vistas de listado sin anon.
--
-- Regenerar: supabase db query --linked -f scripts/db/dump-privileges.sql -o csv

-- 1. Buckets ─────────────────────────────────────────────────────────────────────────────
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES
  ('gate-evidence',            'gate-evidence',            false, 20971520, NULL),
  ('handover-packages',        'handover-packages',        false, NULL,     NULL),
  ('itr-attachments',          'itr-attachments',          false, 10485760, ARRAY['image/jpeg','image/png','image/webp','image/heic','image/heif','application/pdf']),
  ('mgmt-evidence',            'mgmt-evidence',            false, 20971520, NULL),
  ('pid-documents',            'pid-documents',            false, 52428800, ARRAY['application/pdf']),
  ('preservation-attachments', 'preservation-attachments', false, 10485760, ARRAY['image/jpeg','image/png','image/webp','image/heic','image/heif']),
  ('project-documents',        'project-documents',        false, 52428800, NULL),
  ('punch-attachments',        'punch-attachments',        false, 10485760, ARRAY['image/jpeg','image/png','image/webp','image/heic','image/heif']),
  ('test-equipment',           'test-equipment',           false, 10485760, ARRAY['application/pdf','image/jpeg','image/png'])
ON CONFLICT (id) DO UPDATE SET
  public             = EXCLUDED.public,
  file_size_limit    = EXCLUDED.file_size_limit,
  allowed_mime_types = EXCLUDED.allowed_mime_types;

-- 2. Políticas de storage no versionadas ───────────────────────────────────────────────────
-- handover-packages: solo lectura de la propia org; la escritura la hace el service role.
DROP POLICY IF EXISTS handover_storage_select ON storage.objects;
CREATE POLICY handover_storage_select ON storage.objects FOR SELECT TO public
  USING ((bucket_id = 'handover-packages'::text) AND (((storage.foldername(name))[1])::uuid IN ( SELECT get_my_org_ids() AS get_my_org_ids)));

-- pid-documents: leer cualquier miembro de la org; subir y borrar owner/admin/architect.
DROP POLICY IF EXISTS pid_docs_storage_select ON storage.objects;
CREATE POLICY pid_docs_storage_select ON storage.objects FOR SELECT TO public
  USING ((bucket_id = 'pid-documents'::text) AND ((storage.foldername(name))[1] IN ( SELECT (p.id)::text AS id
   FROM (projects p
     JOIN org_members om ON ((om.org_id = p.org_id)))
  WHERE (om.user_id = auth.uid()))));

DROP POLICY IF EXISTS pid_docs_storage_insert ON storage.objects;
CREATE POLICY pid_docs_storage_insert ON storage.objects FOR INSERT TO public
  WITH CHECK ((bucket_id = 'pid-documents'::text) AND ((storage.foldername(name))[1] IN ( SELECT (p.id)::text AS id
   FROM (projects p
     JOIN org_members om ON ((om.org_id = p.org_id)))
  WHERE ((om.user_id = auth.uid()) AND (om.role = ANY (ARRAY['owner'::org_member_role, 'admin'::org_member_role, 'architect'::org_member_role]))))));

DROP POLICY IF EXISTS pid_docs_storage_delete ON storage.objects;
CREATE POLICY pid_docs_storage_delete ON storage.objects FOR DELETE TO public
  USING ((bucket_id = 'pid-documents'::text) AND ((storage.foldername(name))[1] IN ( SELECT (p.id)::text AS id
   FROM (projects p
     JOIN org_members om ON ((om.org_id = p.org_id)))
  WHERE ((om.user_id = auth.uid()) AND (om.role = ANY (ARRAY['owner'::org_member_role, 'admin'::org_member_role, 'architect'::org_member_role]))))));

